import {T,step,v,n,o,p,f,pow,prime,eq,plus,minus,x,y,C,fn,exp,integral,dx,dy,abs,lines,r} from '../../../study/math.js';

const zero=n(0),one=n(1),two=n(2),three=n(3),four=n(4);
const uv=v('u'),du=v('d')+uv,mu=v('μ');
const ln=s=>fn('ln',s),par=s=>p(s);
const neq=o('≠'),gt=o('>'),pm=o('±');

const pathFirstOrder=[
 step('1. Denklemi standart biçime getir ve türünü belirle','1. Put into standard form and classify',lines(prime(y)+plus+f(one,x)+y+eq+pow(y,three),prime(y)+plus+v('P')+par(x)+y+eq+v('Q')+par(x)+pow(y,v('n'))),'Denklem y′ + P(x)y = Q(x)yⁿ biçimindedir (n=3). y³ terimi doğrusallığı bozar; bu standart bir Bernoulli denklemidir.','The ODE has the form y′ + P(x)y = Q(x)yⁿ with n=3. The y³ term breaks linearity; this is a standard Bernoulli equation.'),
 step('2. y=0 dalını kaydet ve u = y^{1−n} dönüşümünü kur','2. Record the y=0 branch and apply u = y^{1−n}',lines(pow(y,three)+o('⇒')+y+eq+zero+o(' ')+v('aşikar çözüm'),uv+eq+pow(y,one+minus+three)+eq+pow(y,minus+two)),'Her terim y³’e bölünmeden önce y=0 çözümü ayrıca kaydedilir. u = y^{−2} dönüşümü ile du/dx = −2 y^{−3} dy/dx elde edilir.','Before dividing by y³, the trivial solution y=0 is recorded. Setting u = y^{−2} gives du/dx = −2 y^{−3} dy/dx.'),
 step('3. u için birinci mertebe doğrusal denkleme indir','3. Reduce to a first-order linear ODE for u',lines(prime(uv)+minus+f(two,x)+uv+eq+minus+two,mu+par(x)+eq+exp(integral(minus+f(two,x)+dx))+eq+pow(x,minus+two)),'Denklem u′ − (2/x)u = −2 doğrusal formuna iner. İntegral çarpanı μ(x) = exp(−2 ln x) = x^{−2} olarak hesaplanır.','The equation reduces to linear form u′ − (2/x)u = −2. The integrating factor is μ(x) = exp(−2 ln x) = x^{−2}.'),
 step('4. u(x) genel çözümünü bul','4. Integrate to find the general solution u(x)',lines(f(v('d'),dx)+par(pow(x,minus+two)+uv)+eq+minus+two+pow(x,minus+two),pow(x,minus+two)+uv+eq+f(two,x)+plus+C+o('⇒')+uv+eq+two+x+plus+C+pow(x,two)),'Sol taraf (x^{−2} u)′ olur. Sağ tarafın integrali 2/x + C verir; x² ile çarpılınca u(x) = 2x + Cx² bulunur.','The LHS is (x^{−2} u)′. Integrating the RHS gives 2/x + C; multiplying by x² yields u(x) = 2x + Cx².'),
 step('5. Geri dönüştür, y=0 dalını ve tanım aralığını ekle','5. Back-substitute, attach the y=0 branch, and note domain',lines(pow(y,two)+eq+f(one,two+x+plus+C+pow(x,two))+o(',')+y+eq+zero),'(2x + Cx²) > 0 aralığında y = ± 1/√(2x + Cx²) genel çözümü geçerlidir. y = 0 çözümü ile birlikte tam çözüm kümesi yazılır.','On 2x + Cx² > 0 the general solution is y = ± 1/√(2x + Cx²). Together with y = 0, the full solution set is established.')
];

const pathReduction=[
 step('1. Eksik değişkeni tanı: x görünmüyor','1. Detect the missing variable: x is absent',lines(y+prime(y,2)+eq+pow(prime(y),two),uv+eq+prime(y)+o(',')+prime(y,2)+eq+uv+f(du,dy)),'Denklemde bağımsız değişken x açıkça yer almaz. y’yi bağımsız değişken seçip y″ = u du/dy yazarız.','The independent variable x does not appear. We make y the independent variable and substitute y″ = u du/dy.'),
 step('2. u = 0 dalını sıfıra bölmeden önce ayır','2. Isolate the u = 0 branch before dividing',lines(y+uv+f(du,dy)+eq+pow(uv,two),uv+eq+zero+o('⇒')+prime(y)+eq+zero+o('⇒')+y+eq+C),'u = 0 kökü y′ = 0 ve y = C sabit çözümlerini verir. Bu dal genel integralde sıfıra bölmeyi önler.','The root u = 0 yields y′ = 0 and the constant solutions y = C. This prevents illegal division by zero in the general integral.'),
 step('3. u ≠ 0 için değişkenleri ayır ve integre et','3. For u ≠ 0 separate variables and integrate',lines(f(du,uv)+eq+f(dy,y),ln(abs(uv))+eq+ln(abs(y))+plus+ln(abs(v('C₁')))+o('⇒')+uv+eq+v('C₁')+y),'du/u = dy/y ayrılır. İntegral ln|u| = ln|y| + ln|C₁| ve buradan u = C₁y bağıntısını üretir.','We separate du/u = dy/y. Integration gives ln|u| = ln|y| + ln|C₁|, leading to u = C₁y.'),
 step('4. dy/dx = C₁y denklemini x’e göre integre et','4. Integrate dy/dx = C₁y with respect to x',lines(f(dy,y)+eq+v('C₁')+dx,ln(abs(y))+eq+v('C₁')+x+plus+v('C₂')+o('⇒')+y+eq+v('A')+exp(v('C₁')+x)),'u = dy/dx yerine konup ikinci kez ayrılır: dy/y = C₁ dx. İntegral y = A e^{C₁x} üstel ailesini verir.','Setting u = dy/dx yields a second separable equation: dy/y = C₁ dx, integrating to the exponential family y = A e^{C₁x}.'),
 step('5. Sabit sayısını doğrula ve tam çözümü yaz','5. Verify constant count and state the complete solution',lines(y+eq+v('A')+exp(v('C₁')+x)+o(',')+v('C₁')+o(',')+v('A')+o(' ')+v('bağımsız sabitler')),'İkinci mertebe denklem tam iki keyfi sabit (A ve C₁) içerir. A=0 seçimi u=0 dalından gelen y=0 çözümünü de kapsar.','The second-order ODE possesses exactly two arbitrary constants (A and C₁). A=0 subsumes the y=0 solution from u=0.')
];

const clinicProblem1=[
 step('1. Standart dy/dx biçiminde dene ve tıkanmayı gör (1 puan)','1. Attempt standard dy/dx and see obstruction (1 point)',lines(y+dx+minus+par(x+plus+pow(y,three))+dy+eq+zero,f(dy,dx)+eq+f(y,x+plus+pow(y,three))),'dy/dx = y/(x + y³) ifadesi y’ye göre doğrusal değildir; paydada x + y³ toplamı ayrılmayı ve homojenliği de engeller.','dy/dx = y/(x + y³) is nonlinear in y; the denominator x + y³ blocks separation and homogeneity.'),
 step('2. Değişkenlerin rolünü ters çevir: dx/dy’ye geç (1 puan)','2. Invert roles of variables: switch to dx/dy (1 point)',lines(f(dx,dy)+eq+f(x+plus+pow(y,three),y)+eq+f(one,y)+x+plus+pow(y,two),f(dx,dy)+minus+f(one,y)+x+eq+pow(y,two)),'Ters türev dx/dy = (x + y³)/y alınır. Denklem x bağımlı değişkenine göre birinci mertebe doğrusal hale gelir: x′ − (1/y)x = y².','Inverting derivatives gives dx/dy = (x + y³)/y. The ODE becomes first-order linear in x: x′ − (1/y)x = y².'),
 step('3. İntegral çarpanını bul ve uygula (1 puan)','3. Find and apply the integrating factor (1 point)',lines(mu+par(y)+eq+exp(integral(minus+f(one,y)+dy))+eq+f(one,y),f(v('d'),dy)+par(f(x,y))+eq+f(one,y)+pow(y,two)+eq+y),'P(y) = −1/y için integral çarpanı μ(y) = 1/y’dir. Sol taraf [x/y]′ tam türevi olur; sağ taraf y kalır.','For P(y) = −1/y, the integrating factor is μ(y) = 1/y. The LHS becomes [x/y]′ while the RHS simplifies to y.'),
 step('4. y’ye göre integre et (1 puan)','4. Integrate with respect to y (1 point)',lines(f(x,y)+eq+f(pow(y,two),two)+plus+C+o('⇒')+x+eq+f(pow(y,three),two)+plus+C+y),'Her iki taraf y’ye göre integre edilir: x/y = y²/2 + C. Buradan x = y³/2 + Cy açık eğri ailesi elde edilir.','Integrating w.r.t. y gives x/y = y²/2 + C, yielding the explicit solution for x: x = y³/2 + Cy.'),
 step('5. Tanım bölgesini ve tekil dalı belirt (1 puan)','5. State domain and the singular branch (1 point)',lines(y+neq+zero+o(' ')+v('için geçerli')+o(',')+y+eq+zero+o(' ')+v('ayrı çözüm')),'Bölme işlemi y ≠ 0 gerektirir. y = 0 asıl diferansiyel denklemi 0 dx − x · 0 = 0 olarak sağlar; çözüm kümesi x = y³/2 + Cy ve y = 0’dır.','Division requires y ≠ 0. The line y = 0 satisfies the original ODE (0 dx − 0 = 0); the complete set is x = y³/2 + Cy and y = 0.')
];

const clinicProblem2=[
 step('1. Standart Bernoulli biçimine getir (1 puan)','1. Bring to standard Bernoulli form (1 point)',lines(x+prime(y)+plus+y+eq+x+pow(y,two),prime(y)+plus+f(one,x)+y+eq+pow(y,two)),'x ≠ 0 için her terim x’e bölünür. Denklem n=2 olan standart bir Bernoulli denklemidir.','Dividing by x ≠ 0 puts the equation into standard Bernoulli form with n=2.'),
 step('2. y = 0 dalını kaydet ve u = y^{−1} dönüşümü yap (1 puan)','2. Record y = 0 and substitute u = y^{−1} (1 point)',lines(y+eq+zero+o(' ')+v('aşikar çözüm'),uv+eq+f(one,y)+o(',')+prime(uv)+minus+f(one,x)+uv+eq+minus+one),'y² ile bölmeden önce y=0 çözümü ayrılır. u = 1/y ile u′ − (1/x)u = −1 doğrusal denklemi kurulur.','Isolate y=0 before dividing by y². With u = 1/y, we obtain the linear equation u′ − (1/x)u = −1.'),
 step('3. Doğrusal denklemi çöz (1 puan)','3. Solve the linear equation (1 point)',lines(mu+par(x)+eq+f(one,x)+o(',')+f(v('d'),dx)+par(f(uv,x))+eq+minus+f(one,x),f(uv,x)+eq+minus+ln(abs(x))+plus+C+o('⇒')+uv+eq+x+par(C+minus+ln(abs(x)))),'İntegral çarpanı μ = 1/x’tir. [u/x]′ = −1/x integre edilince u = x(C − ln|x|) çıkar.','The integrating factor is μ = 1/x. Integrating [u/x]′ = −1/x yields u = x(C − ln|x|).'),
 step('4. y’ye geri dön ve genel çözümü yaz (1 puan)','4. Return to y and write general solution (1 point)',lines(y+eq+f(one,uv)+eq+f(one,x+par(C+minus+ln(abs(x))))),'u = 1/y yerine konunca genel çözüm y = 1 / [x(C − ln|x|)] olarak bulunur.','Substituting u = 1/y gives the general solution y = 1 / [x(C − ln|x|)].'),
 step('5. Dalları ve tanım aralıklarını özetle (1 puan)','5. Summarize branches and domains (1 point)',lines(y+eq+f(one,x+par(C+minus+ln(abs(x))))+o(',')+y+eq+zero+o(',')+x+gt+zero),'Logaritma nedeniyle x > 0 dalı alınır; paydanın sıfır olduğu x = e^C noktası düşey asimptottur. y=0 aşikar çözümü unutulmamalıdır.','The logarithm requires x > 0; x = e^C is a vertical asymptote. The trivial branch y = 0 must be included.')
];

const clinicProblem3=[
 step('1. Homojenlik ve tamlık testlerini karşılaştır (1 puan)','1. Compare homogeneity and exactness tests (1 point)',lines(par(pow(x,two)+plus+pow(y,two))+dx+minus+two+x+y+dy+eq+zero,f(v('∂M'),v('∂y'))+eq+two+y+o(',')+f(v('∂N'),v('∂x'))+eq+minus+two+y),'M_y = 2y ≠ N_x = −2y olduğundan denklem tam değildir; ancak M ve N terimlerinin tamamı 2. dereceden homojendir.','Since M_y = 2y ≠ N_x = −2y the ODE is not exact; however, both M and N are homogeneous of degree 2.'),
 step('2. En kısa yolu seç: tek değişkenli integral çarpanı (1 puan)','2. Select shortest path: single-variable integrating factor (1 point)',lines(f(f(v('∂M'),v('∂y'))+minus+f(v('∂N'),v('∂x')),v('N'))+eq+f(four+y,minus+two+x+y)+eq+minus+f(two,x)),'(M_y − N_x)/N = 4y / (−2xy) = −2/x yalnız x’e bağlıdır! Bu, homojen dönüşümünden çok daha kısa bir yol sunar.','(M_y − N_x)/N = −2/x depends solely on x! This offers a much faster route than the homogeneous substitution.'),
 step('3. Çarpanı hesapla ve tam denklemi kur (1 puan)','3. Compute the multiplier and form the exact equation (1 point)',lines(mu+par(x)+eq+exp(integral(minus+f(two,x)+dx))+eq+f(one,pow(x,two)),par(one+plus+f(pow(y,two),pow(x,two)))+dx+minus+f(two+y,x)+dy+eq+zero),'μ(x) = 1/x² çarpanı ile çarpılınca yeni denklem tam hale gelir: ∂(1 + y²/x²)/∂y = 2y/x² = ∂(−2y/x)/∂x.','Multiplying by μ(x) = 1/x² makes the equation exact: ∂(1 + y²/x²)/∂y = 2y/x² = ∂(−2y/x)/∂x.'),
 step('4. Potansiyeli integre et (1 puan)','4. Integrate the potential (1 point)',lines(v('u')+par(x+o(',')+y)+eq+integral(par(one+plus+f(pow(y,two),pow(x,two)))+dx)+eq+x+minus+f(pow(y,two),x)+plus+v('h')+par(y),v('h')+prime(par(y))+eq+zero+o('⇒')+x+minus+f(pow(y,two),x)+eq+C),'Potansiyel u(x,y) = x − y²/x = C düzey eğrilerini verir. Düzenlenince x² − Cx − y² = 0 elde edilir.','The potential u(x,y) = x − y²/x = C yields the level curves x² − Cx − y² = 0.'),
 step('5. Yöntem seçim gerekçesini ve kısıtları yaz (1 puan)','5. State method rationale and constraints (1 point)',lines(pow(x,two)+minus+C+x+minus+pow(y,two)+eq+zero+o(',')+x+neq+zero),'x = 0 noktası dışlanır. Homojen v=y/x yolu da aynı sonuca ulaşır; ancak tek değişkenli çarpan aramak integrasyonu yarı yarıya kısaltır.','The line x = 0 is excluded. Homogeneous v=y/x gives the same result, but testing (M_y − N_x)/N cuts work in half.')
];

const clinicProblem4=[
 step('1. Clairaut yapısını hemen tanı (1 puan)','1. Recognize Clairaut form immediately (1 point)',lines(y+eq+x+prime(y)+plus+f(one,prime(y)),y+eq+x+uv+plus+f(one,uv)),'Denklem y = x y′ + f(y′) biçiminde açık bir Clairaut denklemidir; burada f(p) = 1/p’dir. Mertebe 1’dir.','The equation is explicitly in Clairaut form y = x y′ + f(y′) with f(p) = 1/p. The order is 1.'),
 step('2. x’e göre türev al ve çarpanlara ayır (1 puan)','2. Differentiate w.r.t. x and factor (1 point)',lines(uv+eq+uv+plus+par(x+minus+f(one,pow(uv,two)))+f(du,dx),par(x+minus+f(one,pow(uv,two)))+f(du,dx)+eq+zero),'Türev alındığında sol ve sağdaki p=y′ sadeleşir; geriye (x − 1/p²) dp/dx = 0 kalır.','Differentiating cancels p=y′ on both sides, leaving (x − 1/p²) dp/dx = 0.'),
 step('3. dp/dx = 0 dalından doğru ailesini yaz (1 puan)','3. Write line family from dp/dx = 0 (1 point)',lines(f(du,dx)+eq+zero+o('⇒')+uv+eq+C+o('⇒')+y+eq+C+x+plus+f(one,C)),'Birinci dal dp/dx = 0 genel çözümü üretir: y = Cx + 1/C doğru ailesi (C ≠ 0).','The first branch dp/dx = 0 yields the general solution: lines y = Cx + 1/C (C ≠ 0).'),
 step('4. İkinci daldan tekil zarf çözümünü çıkar (1 puan)','4. Derive the singular envelope from the second branch (1 point)',lines(x+minus+f(one,pow(uv,two))+eq+zero+o('⇒')+pow(uv,two)+eq+f(one,x),y+eq+x+par(pm+f(one,v('√x')))+plus+par(pm+v('√x'))+eq+pm+two+v('√x')),'x = 1/p² dalı p² = 1/x (x > 0 için) verir. y = xp + 1/p içine konunca y = ± 2√x, yani y² = 4x parabolü elde edilir.','The branch x = 1/p² gives p² = 1/x (for x > 0). Substituting gives y = ± 2√x, or the parabola y² = 4x.'),
 step('5. Çözüm kümesini ve tekil zarfı doğrula (1 puan)','5. Verify solution set and singular envelope (1 point)',lines(y+eq+C+x+plus+f(one,C)+o(' ')+v('ve')+o(' ')+pow(y,two)+eq+four+x+o(',')+x+gt+zero),'Doğru ailesi ve tekil parabol birlikte verilir. y² = 4x parabolünün teğetleri tam olarak bu doğru ailesini oluşturur; hiçbir C değeri zarfı üretemez.','Both the line family and the singular parabola are reported. The lines are tangent to y² = 4x; no C yields the envelope.')
];

